from __future__ import annotations

import re
from collections import defaultdict
from pathlib import Path
from typing import Any


_HEADER_RE = re.compile(r"^\[([^\[\]]+)\]$")
_CHOICE_PREFIX_RE = re.compile(r"^(\d+)\.\s+(.+)$")
_NODE_FIELDS = {"id", "text", "speaker", "type"}
_EDGE_FIELDS = {"from", "to", "text"}


class _Context:
    def __init__(self, label: str, node_id: str) -> None:
        self.label = label
        self.node_id = node_id
        self.line_ids: list[str] = []
        self.choice_node_id: str | None = None


class _GraphBuilder:
    def __init__(self) -> None:
        self.nodes: list[dict[str, str]] = []
        self.node_by_id: dict[str, dict[str, str]] = {}
        self.edges: list[dict[str, str]] = []
        self.resolved_ids: set[str] = set()
        self.choice_edge_counts: dict[str, int] = {}
        self.context_occurrences: defaultdict[str, int] = defaultdict(int)

    def ensure_placeholder(self, node_id: str) -> None:
        if node_id == "End" or node_id in self.node_by_id:
            return
        node = {"id": node_id, "text": "", "speaker": "", "type": "line"}
        self.nodes.append(node)
        self.node_by_id[node_id] = node

    def allocate_id(self, base: str) -> str:
        if base not in self.node_by_id:
            return base
        suffix = 2
        while f"{base}_{suffix}" in self.node_by_id:
            suffix += 1
        return f"{base}_{suffix}"

    def declare_context(self, label: str) -> _Context:
        self.context_occurrences[label] += 1
        occurrence = self.context_occurrences[label]
        base = label if occurrence == 1 else f"{label}_{occurrence}"

        if base in self.node_by_id and base not in self.resolved_ids:
            node_id = base
        else:
            node_id = self.allocate_id(base)
        self.ensure_placeholder(node_id)
        self.resolved_ids.add(node_id)
        return _Context(label, node_id)

    def update_node(self, node_id: str, *, text: str, speaker: str, node_type: str) -> None:
        self.ensure_placeholder(node_id)
        node = self.node_by_id[node_id]
        node.update(text=text, speaker=speaker, type=node_type)
        self.resolved_ids.add(node_id)

    def add_edge(self, source: str, target: str, text: str = "") -> None:
        if source not in self.node_by_id:
            raise ValueError(f"Edge source {source!r} does not exist")
        if target != "End":
            self.ensure_placeholder(target)
        self.edges.append({"from": source, "to": target, "text": text})

    def make_line_node(self, context: _Context, speaker: str, text: str) -> str:
        if not context.line_ids and context.choice_node_id is None:
            node_id = context.node_id
        else:
            if not context.line_ids:
                base = f"{context.node_id}_line"
            else:
                base = f"{context.node_id}_{len(context.line_ids) + 1}"
            node_id = self.allocate_id(base)
        self.update_node(node_id, text=text, speaker=speaker, node_type="line")
        context.line_ids.append(node_id)
        return node_id

    def make_choice_node(self, context: _Context) -> str:
        if context.choice_node_id is not None:
            return context.choice_node_id

        if context.line_ids:
            node_id = self.allocate_id(f"{context.node_id}_choice")
        else:
            node_id = context.node_id
        self.update_node(node_id, text="", speaker="", node_type="choice")
        context.choice_node_id = node_id
        self.choice_edge_counts[node_id] = 0

        if context.line_ids:
            self.add_edge(context.line_ids[-1], node_id)
        return node_id

    def add_choice_edge(self, context: _Context, choice_text: str, target: str) -> None:
        choice_node_id = self.make_choice_node(context)
        self.add_edge(choice_node_id, target, choice_text)
        self.choice_edge_counts[choice_node_id] += 1

    def result(self) -> dict[str, list[dict[str, str]]]:
        return {"nodes": self.nodes, "edges": self.edges}


def _split_transition(content: str, line_number: int) -> tuple[str, str]:
    arrow_index = content.rfind("->")
    if arrow_index < 0:
        raise ValueError(f"Malformed dialogue on line {line_number}: missing '->'")

    left = content[:arrow_index].strip()
    target = content[arrow_index + 2 :].strip()
    if not left or not target:
        raise ValueError(f"Malformed dialogue on line {line_number}: missing text or target")
    return left, target


def _parse_entry(raw_line: str, line_number: int) -> tuple[str, str, str] | tuple[str, str]:
    choice_match = _CHOICE_PREFIX_RE.fullmatch(raw_line)
    if choice_match:
        choice_body, target = _split_transition(choice_match.group(2), line_number)
        return "choice", choice_body, target

    left, target = _split_transition(raw_line, line_number)
    colon_index = left.find(":")
    if colon_index < 0:
        raise ValueError(f"Malformed content on line {line_number}: expected speaker or numbered choice")

    speaker = left[:colon_index].strip()
    dialogue = left[colon_index + 1 :].strip()
    if not speaker or not dialogue:
        raise ValueError(f"Malformed speaker line {line_number}: missing speaker or dialogue")
    return "line", speaker, dialogue, target


def validate_graph(
    graph: dict[str, Any],
    *,
    resolved_ids: set[str] | None = None,
    choice_edge_counts: dict[str, int] | None = None,
) -> None:
    """Validate the serialized graph and raise ValueError for invalid input."""
    if set(graph) != {"nodes", "edges"}:
        raise ValueError("Graph must contain exactly 'nodes' and 'edges'")
    if not isinstance(graph["nodes"], list) or not isinstance(graph["edges"], list):
        raise ValueError("Graph nodes and edges must be lists")
    if not graph["nodes"]:
        raise ValueError("Graph must contain at least one node")

    node_ids: set[str] = set()
    for node in graph["nodes"]:
        if not isinstance(node, dict) or set(node) != _NODE_FIELDS:
            raise ValueError("Every node must have exactly id, text, speaker, and type fields")
        node_id = node["id"]
        if not isinstance(node_id, str) or not node_id:
            raise ValueError("Every node must have a non-empty string id")
        if node_id in node_ids:
            raise ValueError(f"Duplicate node id: {node_id!r}")
        if node["type"] not in {"line", "choice"}:
            raise ValueError(f"Unsupported node type for {node_id!r}: {node['type']!r}")
        node_ids.add(node_id)

    outgoing: defaultdict[str, list[str]] = defaultdict(list)
    for edge in graph["edges"]:
        if not isinstance(edge, dict) or set(edge) != _EDGE_FIELDS:
            raise ValueError("Every edge must have exactly from, to, and text fields")
        source = edge["from"]
        target = edge["to"]
        if source not in node_ids:
            raise ValueError(f"Edge source {source!r} does not exist")
        if target != "End" and target not in node_ids:
            raise ValueError(f"Edge target {target!r} does not exist")
        outgoing[source].append(target)

    if resolved_ids is not None:
        unresolved = {
            edge["to"]
            for edge in graph["edges"]
            if edge["to"] != "End" and edge["to"] not in resolved_ids
        }
        if unresolved:
            names = ", ".join(repr(name) for name in sorted(unresolved))
            raise ValueError(f"Missing dialogue header/context for target(s): {names}")

    root_id = graph["nodes"][0]["id"]
    reachable = {root_id}
    stack = [root_id]
    while stack:
        source = stack.pop()
        for target in outgoing[source]:
            if target != "End" and target not in reachable:
                reachable.add(target)
                stack.append(target)
    unreachable = node_ids - reachable
    if unreachable:
        names = ", ".join(repr(name) for name in sorted(unreachable))
        raise ValueError(f"Unreachable node(s): {names}")

    if choice_edge_counts is not None:
        for node_id, expected_count in choice_edge_counts.items():
            actual_count = sum(1 for edge in graph["edges"] if edge["from"] == node_id)
            if actual_count != expected_count or expected_count == 0:
                raise ValueError(f"Choice node {node_id!r} has invalid outgoing choice edges")


def parse_script(text: str) -> dict[str, list[dict[str, str]]]:
    """Parse script text into a deterministic, validated dialogue graph."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    builder = _GraphBuilder()
    current_context: _Context | None = None

    for line_number, raw_line in enumerate(text.splitlines(), start=1):
        stripped = raw_line.strip()
        if not stripped:
            continue

        header_match = _HEADER_RE.fullmatch(stripped)
        if header_match:
            label = header_match.group(1).strip()
            if not label:
                raise ValueError(f"Empty header on line {line_number}")
            if label == "End":
                raise ValueError("'End' is reserved for terminal edge targets")
            current_context = builder.declare_context(label)
            continue

        if current_context is None:
            raise ValueError(f"Malformed content on line {line_number}: no active header")

        parsed = _parse_entry(stripped, line_number)
        if parsed[0] == "choice":
            _, choice_text, target = parsed
            builder.add_choice_edge(current_context, choice_text.strip(), target)
        else:
            _, speaker, dialogue, target = parsed
            line_id = builder.make_line_node(current_context, speaker, dialogue)
            builder.add_edge(line_id, target)

    graph = builder.result()
    validate_graph(
        graph,
        resolved_ids=builder.resolved_ids,
        choice_edge_counts=builder.choice_edge_counts,
    )
    return graph


def _escape_dot(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', '\\"').replace("\r", "\\r").replace("\n", "\\n")


def graph_to_dot(graph: dict[str, list[dict[str, str]]]) -> str:
    """Serialize a validated graph to a Graphviz DOT directed graph."""
    lines = ["digraph dialogue {"]
    for node in graph["nodes"]:
        if node["type"] == "choice":
            label = node["text"] or node["id"]
            shape = "diamond"
        else:
            label = f"{node['speaker']}: {node['text']}" if node["speaker"] else node["text"] or node["id"]
            shape = "box"
        lines.append(f'  "{_escape_dot(node["id"])}" [label="{_escape_dot(label)}", shape={shape}];')

    for edge in graph["edges"]:
        label = f' [label="{_escape_dot(edge["text"])}"]' if edge["text"] else ""
        lines.append(f'  "{_escape_dot(edge["from"])}" -> "{_escape_dot(edge["to"])}"{label};')
    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> None:
    script_path = Path("/app/script.txt")
    graph_path = Path("/app/dialogue.json")
    dot_path = Path("/app/dialogue.dot")

    graph = parse_script(script_path.read_text(encoding="utf-8"))

    import json

    graph_path.write_text(json.dumps(graph, indent=2) + "\n", encoding="utf-8")
    dot_path.write_text(graph_to_dot(graph), encoding="utf-8")


if __name__ == "__main__":
    main()
